import fs from 'node:fs';import pg from './robot-panol/runtime/node_modules/pg/lib/index.js';import {buildProductGroups} from '../src/features/panol/stockGrupos.js';process.loadEnvFile('.env.audit.local');const e=process.env;const c=new pg.Client({host:e.KLASEA_AUDIT_DB_HOST,port:+e.KLASEA_AUDIT_DB_PORT,user:e.KLASEA_AUDIT_DB_USER,password:e.KLASEA_AUDIT_DB_PASSWORD,database:e.KLASEA_AUDIT_DB_NAME,ssl:{rejectUnauthorized:false},connectionTimeoutMillis:10000});await c.connect();try{console.log(JSON.stringify((await c.query("select current_user,has_table_privilege(current_user,'panol_materiales','UPDATE') as can_update")).rows));const refs=await c.query(`select c.table_name,c.column_name from information_schema.columns c where c.table_schema='public' and c.column_name in ('descripcion','description') and c.table_name not like '%backup%' and c.table_name not like '%audit%' and c.table_name not like 'v_%'`);const found={};for(const {table_name:t,column_name:k}of refs.rows){const r=await c.query(`select * from public."${t}" where "${k}" ~* 'composite|anti.?ruido|antirruido'`);if(r.rows.length)found[t]=r.rows;}fs.writeFileSync('backups/placas-antiruido-20261103/referencias-antes.json',JSON.stringify(found,null,2));console.log(JSON.stringify(Object.fromEntries(Object.entries(found).map(([t,r])=>[t,{n:r.length,names:[...new Set(r.map(x=>x.descripcion||x.description))]}]))));const snaps=JSON.parse(fs.readFileSync('backups/placas-antiruido-20261103/snapshots.json'));const groups=buildProductGroups(snaps,'todas');console.log(JSON.stringify(groups.map(g=>({label:g.label,total:g.total,libre:g.stockLibre,reservado:g.stockReservado,locations:g.locations}))));console.log(JSON.stringify({obras:(await c.query('select id,codigo from produccion_obras where id=any($1::uuid[])',[[...new Set(snaps.map(x=>x.obra_id).filter(Boolean))]])).rows}));}finally{await c.end()}
